<?php
require_once __DIR__.'/../config/init.php';require_once __DIR__.'/../auth/verificar.php';
if(($_SESSION['usuario_perfil']??'')!=='ADMIN'){http_response_code(403);exit('Acesso negado.');}
if($_SERVER['REQUEST_METHOD']==='POST'){ $nome=trim($_POST['nome']);$usuario=trim($_POST['usuario']);$email=trim($_POST['email']);$senha=$_POST['senha'];$perfil=$_POST['perfil'];if($nome&&$usuario&&$email&&$senha)$pdo->prepare("INSERT INTO usuarios(nome,usuario,email,senha,perfil) VALUES(?,?,?,?,?)")->execute([$nome,$usuario,$email,password_hash($senha,PASSWORD_DEFAULT),$perfil]);}
$users=$pdo->query("SELECT nome,usuario,email,perfil,ativo FROM usuarios ORDER BY nome")->fetchAll();?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuários</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../partials/menu.php';?><main class="main"><h1>Usuários</h1><div class="panel"><form method="post" class="form-grid"><label>Nome<input name="nome" required></label><label>Usuário<input name="usuario" required></label><label>E-mail<input type="email" name="email" required></label><label>Senha<input type="password" name="senha" required></label><label>Perfil<select name="perfil"><option>OPERADOR</option><option>ADMIN</option></select></label><div class="actions"><button class="btn primary">Cadastrar usuário</button></div></form></div><div class="panel"><table><thead><tr><th>Nome</th><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['nome'])?></td><td><?=htmlspecialchars($u['usuario'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=$u['perfil']?></td><td><?=$u['ativo']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>